class Solution:
    def minCost(self, nums: list[int], x: int) -> int:
        n = len(nums)
        cur_costs = list(nums)
        ans = sum(cur_costs)
        for k in range(1, n):
            cur_costs = [min(cur_costs[i], nums[(i - k) % n]) for i in range(n)]
            ans = min(ans, sum(cur_costs) + k * x)
        return ans

class Solution {
public:
    long long minCost(vector<int>& nums, int x) {
        int n = nums.size();
        vector<long long> cur_costs(nums.begin(), nums.end());
        long long ans = 0;
        for (long long c : cur_costs) ans += c;
        for (int k = 1; k < n; ++k) {
            long long cur_sum = 0;
            for (int i = 0; i < n; ++i) {
                cur_costs[i] = min(cur_costs[i], (long long)nums[(i - k + n) % n]);
                cur_sum += cur_costs[i];
            }
            ans = min(ans, cur_sum + 1LL * k * x);
        }
        return ans;
    }
};

class Solution {
    public long minCost(int[] nums, int x) {
        int n = nums.length;
        long[] curCosts = new long[n];
        long ans = 0;
        for (int i = 0; i < n; i++) {
            curCosts[i] = nums[i];
            ans += curCosts[i];
        }
        for (int k = 1; k < n; k++) {
            long curSum = 0;
            for (int i = 0; i < n; i++) {
                curCosts[i] = Math.min(curCosts[i], nums[(i - k + n) % n]);
                curSum += curCosts[i];
            }
            ans = Math.min(ans, curSum + (long) k * x);
        }
        return ans;
    }
}

var minCost = function(nums, x) {
    const n = nums.length;
    const curCosts = nums.map(v => BigInt(v));
    let ans = curCosts.reduce((a, b) => a + b, 0n);
    const bigX = BigInt(x);
    for (let k = 1; k < n; k++) {
        let curSum = 0n;
        for (let i = 0; i < n; i++) {
            const rotated = BigInt(nums[(i - k + n) % n]);
            if (rotated < curCosts[i]) curCosts[i] = rotated;
            curSum += curCosts[i];
        }
        const total = curSum + BigInt(k) * bigX;
        if (total < ans) ans = total;
    }
    return Number(ans);
};
